group('gh-1199 AC6 — the installer IT step respects the flake quarantine', () {
  test('the IT target routes through apply_quarantine.py', () {
    final job = read(ci).split('  installer-portability:')[1];
    expect(
      job,
      contains('| python3 scripts/apply_quarantine.py'),
      reason:
          'the leg runs the known-flaky wizard E2 test directly, so a '
          'site/**-only PR re-arms the flake as a merge blocker the '
          'quarantine claims to shield (pr-1797 review thread '
          'PRRT_kwDOTXdlLc6vepoh)',
    );
  });

  test('an emptied filter SKIPS the step — never a bare dart test', () {
    final job = read(ci).split('  installer-portability:')[1];
    expect(
      job,
      contains('if [ -z "$targets" ]'),
      reason:
          'the IT step has exactly one target; with it quarantined the '
          'filter prints nothing and a bare `dart test` would run the '
          'WHOLE suite on the installer runner',
    );
    expect(job, contains('exit 0'), reason: 'the skip is a pass, not a red');
  });

  test('the UT step stays unfiltered (site tests are never quarantined)', () {
    final job = read(ci).split('  installer-portability:')[1];
    expect(
      job,
      contains(
        'dart test test/site/setup_sh_portability_test.dart '
        'test/site/installer_golden_test.dart',
      ),
      reason:
          'the quarantine only shields integration-tagged files; the '
          'template/golden proof must never learn to skip',
    );
  });
});

