  /// The IT step's own body — job slice cut at the step name, then at
  /// the next job header, so assertions can't leak into OTHER legs'
  /// quarantine plumbing (the pty shards pipe through the same filter).
  String itStep() =>
      read(ci)
          .split('  installer-portability:')[1]
          .split(
            '- name: IT — piped wizard under dash/busybox/bash (AC2-AC5)',
          )[1]
          .split('\n  hostile-env:')[0];

