Future<_FakeShellJob> _waitForJob(_FakeBackgroundEnv env) async {
  for (var i = 0; i < 100 && env.jobs.isEmpty; i++) {
    await Future<void>.delayed(Duration.zero);
  }
  return env.jobs.single;
}

